python3 -c "
import urllib.request
from bs4 import BeautifulSoup

url = 'https://exdesktop.xyz/docs/'
req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
html = urllib.request.urlopen(req).read().decode('utf-8')
soup = BeautifulSoup(html, 'html.parser')

sections = []
current_h2 = None
current_h3 = None

for el in soup.find_all(['h2', 'h3', 'p', 'pre', 'table', 'ul', 'ol']):
    tag = el.name
    text = el.text.strip()
    if tag == 'h2':
        current_h2 = {'title': text, 'subsections': [], 'content': []}
        sections.append(current_h2)
        current_h3 = None
    elif tag == 'h3':
        current_h3 = {'title': text, 'content': []}
        if current_h2:
            current_h2['subsections'].append(current_h3)
    else:
        target = current_h3 if current_h3 else current_h2
        if target:
            if tag == 'table':
                rows = []
                for tr in el.find_all('tr'):
                    cells = [td.get_text(strip=True) for td in tr.find_all(['th', 'td'])]
                    if cells:
                        rows.append(cells)
                target['content'].append({'type': 'table', 'rows': rows})
            elif tag in ['ul', 'ol']:
                items = [li.get_text(strip=True) for li in el.find_all('li')]
                target['content'].append({'type': 'list', 'items': items})
            elif tag == 'pre':
                target['content'].append({'type': 'code', 'code': el.get_text()})
            elif tag == 'p':
                target['content'].append({'type': 'p', 'text': text})

import json
with open('docs_full_rich.json', 'w', encoding='utf-8') as f:
    json.dump(sections, f, ensure_ascii=False, indent=2)

print('Saved rich docs. Total h2 sections:', len(sections))
for s in sections:
    print(f\"{s['title']} ({len(s['content'])} items, {len(s['subsections'])} sub)\")
"

